// ── ASLI USE: partial application ──
function partial<A extends any[], B extends any[], R>(
  fn: (...args: [...A, ...B]) => R,
  ...bound: A
): (...rest: B) => R {
  return (...rest) => fn(...bound, ...rest);
}

