abstract class Shape {
  constructor(public name: string) {}

  // POORA — sabko muft milta hai
  describe(): string {
    return `${this.name}: area ${this.area()}`;
  }

  // KHAALI — bachche ko likhna hi padega
  abstract area(): number;

  // abstract property bhi ho sakti hai
  abstract readonly sides: number;
}

// new Shape("x");   ✗ Cannot create an instance of an abstract class

class Circle extends Shape {
  readonly sides = 0;
  constructor(private r: number) { super("circle"); }
  area() { return Math.PI * this.r ** 2; }
}

// class Square extends Shape { }
//       ✗ does not implement 'area', 'sides'   ← compiler rok deta hai

// Abstract class ko TYPE ki tarah use kar sakte ho:
function print(s: Shape) { console.log(s.describe()); }
print(new Circle(2));       // ✓

// Constructor type chahiye (factory ke liye):
type ShapeCtor = new (...args: any[]) => Shape;
function make(C: ShapeCtor) { return new C(); }
// make(Shape);   ✗ abstract class pass nahi kar sakte

