// Event map — naam se payload ka rishta
type Events = {
  "user:login":  { userId: string; at: Date };
  "user:logout": { userId: string };
  "cart:add":    { itemId: string; qty: number };
};

class Emitter<E extends Record<string, unknown>> {
  #listeners: { [K in keyof E]?: ((p: E[K]) => void)[] } = {};

  on<K extends keyof E>(event: K, fn: (payload: E[K]) => void) {
    (this.#listeners[event] ??= []).push(fn);
    return () => this.off(event, fn);
  }

  off<K extends keyof E>(event: K, fn: (payload: E[K]) => void) {
    this.#listeners[event] = (this.#listeners[event] ?? []).filter(f => f !== fn);
  }

  emit<K extends keyof E>(event: K, payload: E[K]) {
    (this.#listeners[event] ?? []).forEach(fn => {
      try { fn(payload); } catch (e) { console.error(e); }
    });
  }
}

