// Constructor type — mixin ka aadhaar
type Ctor<T = {}> = new (...args: any[]) => T;

// Mixin = function jo class leta hai, class deta hai
function Timestamped<T extends Ctor>(Base: T) {
  return class extends Base {
    createdAt = new Date();
    touch() { return this.createdAt; }
  };
}

function Serializable<T extends Ctor>(Base: T) {
  return class extends Base {
    toJSON() { return JSON.stringify(this); }
  };
}

class Model { constructor(public id: string) {} }

// Chain karo
