// TS 5.0+ standard decorator -- method decorator
function log<T extends (...a: any[]) => any>(
  target: T,
  ctx: ClassMethodDecoratorContext
) {
  return function (this: unknown, ...args: any[]) {
    console.log(`-> ${String(ctx.name)}`, args);
    const out = target.apply(this, args);
    console.log(`<- ${String(ctx.name)}`, out);
    return out;
  } as T;
}

class Calc {
  @log
  add(a: number, b: number) { return a + b; }
}

new Calc().add(2, 3);
// -> add [2, 3]
// <- add 5

// (a) side-effect -- registry mein daal do
const registry = new Map<string, new () => unknown>();

function Entity(table: string) {          // factory
  return function <T extends new (...a: any[]) => any>(
    cls: T, ctx: ClassDecoratorContext
  ) {
    registry.set(table, cls);
    return cls;
  };
}

@Entity('users')
class User { constructor(public name = '') {} }

// (b) replace -- nayi class return karo
function withTimestamp<T extends new (...a: any[]) => object>(cls: T) {
  return class extends cls {
    createdAt = new Date();
  };
}

@withTimestamp
class Post { title = ''; }
// (new Post() as any).createdAt -> Date

// memoize -- har instance ka apna cache
function memo<T extends (...a: any[]) => any>(
  target: T, ctx: ClassMethodDecoratorContext
) {
  const caches = new WeakMap<object, Map<string, any>>();
  return function (this: object, ...args: any[]) {
    let c = caches.get(this);
    if (!c) { c = new Map(); caches.set(this, c); }
    const key = JSON.stringify(args);
    if (!c.has(key)) c.set(key, target.apply(this, args));
    return c.get(key);
  } as T;
}

class Math2 {
  @memo
  fib(n: number): number { return n < 2 ? n : this.fib(n-1) + this.fib(n-2); }
}

// field decorator -- value ko transform karo
function upper(_t: undefined, ctx: ClassFieldDecoratorContext) {
  return (init: string) => init.toUpperCase();
}
class P { @upper name = 'mayank'; }   // 'MAYANK'

function tag(name: string) {
  console.log(`factory: ${name}`);              // factory: upar se neeche
  return function <T extends (...a: any[]) => any>(t: T, _c: any) {
    console.log(`apply: ${name}`);              // apply: neeche se upar
    return function (this: any, ...a: any[]) {
      console.log(`in ${name}`);
      const r = t.apply(this, a);
      console.log(`out ${name}`);
      return r;
    } as T;
  };
}

class S { @tag('A') @tag('B') run() { console.log('  ASLI'); } }

// define time: factory: A, factory: B, apply: B, apply: A
new S().run();
// in A -> in B ->   ASLI -> out B -> out A

